import pathlib, re
src = pathlib.Path('liquid-orb-base.html').read_text()
STYLE = '\n    html, body { width: 100%; height: 100%; margin: 0; }\n    body {\n      overflow: hidden;\n      display: grid;\n      place-items: center;\n      background:\n        radial-gradient(900px 640px at 50% 38%, #eceded, #e7e8ea 58%, #dfe1e4 100%);\n      font-family: -apple-system, "SF Pro Display", "Helvetica Neue", system-ui, sans-serif;\n      transition: background 520ms ease;\n    }\n    /* ── Dark テーマ（クロスフェード） ── */\n    body.dark {\n      background:\n        radial-gradient(900px 640px at 50% 38%, #23262c, #1b1e23 58%, #141619 100%);\n    }\n    #status { position: fixed; inset: 0; display: grid; place-items: center; color: #333; font: 14px system-ui; pointer-events: none; }\n    #status[hidden] { display: none; }\n\n    /* ── 写真の構図: 楕円（ピル）＋ 手前のシャボン玉。クリックで切替 ── */\n    .scene {\n      position: relative;\n      width: 560px; height: 360px;\n      border: none; padding: 0; background: none;\n      cursor: pointer;\n      font: inherit;\n      -webkit-tap-highlight-color: transparent;\n    }\n    .scene:focus-visible { outline: 3px solid #4a7cff; outline-offset: 10px; border-radius: 24px; }\n\n    .pill {\n      position: absolute;\n      left: 90px; top: 120px;\n      width: 440px; height: 120px;\n      border-radius: 999px;\n      background: linear-gradient(180deg, #f1f2f4 0%, #e9eaec 55%, #e4e5e8 100%);\n      box-shadow:\n        0 22px 34px -16px rgba(30, 34, 44, 0.35),\n        0 6px 12px rgba(30, 34, 44, 0.10),\n        inset 0 2px 2px rgba(255, 255, 255, 0.95),\n        inset 0 -10px 18px rgba(30, 34, 44, 0.08),\n        inset 0 0 0 1px rgba(255, 255, 255, 0.5);\n      transition: background 520ms ease, box-shadow 520ms ease;\n    }\n    body.dark .pill {\n      background: linear-gradient(180deg, #24272d 0%, #1c1f23 55%, #17191d 100%);\n      box-shadow:\n        0 24px 38px -16px rgba(0, 0, 0, 0.6),\n        0 6px 12px rgba(0, 0, 0, 0.35),\n        inset 0 2px 2px rgba(255, 255, 255, 0.12),\n        inset 0 -10px 18px rgba(0, 0, 0, 0.4),\n        inset 0 0 0 1px rgba(255, 255, 255, 0.06);\n    }\n\n    /* ラベルはレンズの反対側（動画準拠）。テーマで入れ替わる */\n    .lab {\n      position: absolute; top: 50%;\n      transform: translateY(-50%);\n      font-size: 40px; font-weight: 600; letter-spacing: 0.01em;\n      color: #3d4148;\n      transition: opacity 380ms ease, color 520ms ease;\n    }\n    body.dark .lab { color: #e8eaee; }\n    .lab-light { right: 64px; opacity: 1; }\n    .lab-dark  { left: 70px;  opacity: 0; }\n    body.dark .lab-light { opacity: 0; }\n    body.dark .lab-dark  { opacity: 1; }\n\n    /* ── 球のキャリア（slot + icon を一緒に運ぶ） ── */\n    .carrier {\n      position: absolute;\n      left: 0; top: 30px;\n      width: 284px; height: 284px;\n      transform: translateX(var(--x, 0px));\n      transition: transform 640ms cubic-bezier(0.34, 1.42, 0.46, 1);\n      pointer-events: none;\n    }\n    body.dark .carrier { --x: 276px; }\n    .scene.is-moving .carrier { animation: squash 640ms cubic-bezier(0.4, 0, 0.4, 1); }\n    @keyframes squash {\n      0%   { scale: 1 1; }\n      32%  { scale: 1.12 0.91; }\n      64%  { scale: 0.95 1.04; }\n      100% { scale: 1 1; }\n    }\n\n    .orb-slot {\n      position: absolute; inset: 0;\n      border-radius: 50%;\n      overflow: hidden;\n      filter:\n        drop-shadow(0 26px 30px rgba(30, 34, 44, 0.30))\n        drop-shadow(0 8px 12px rgba(30, 34, 44, 0.12));\n    }\n    body.dark .orb-slot {\n      filter:\n        drop-shadow(0 26px 30px rgba(0, 0, 0, 0.55))\n        drop-shadow(0 0 22px rgba(190, 210, 255, 0.10));\n    }\n    canvas {\n      display: block;\n      width: 300px; height: 300px;\n      margin: -8px 0 0 -8px;\n    }\n\n    /* 球内アイコン。白球に白では見えないので、ラベルと同じ濃灰＋淡い白暈 */\n    .orb-icon {\n      position: absolute; inset: 0;\n      display: grid;\n      place-items: center;\n      color: #3d4148;\n      filter: drop-shadow(0 0 10px rgba(255, 255, 255, 0.9));\n    }\n    body.dark .orb-icon {\n      color: #e8eaee;\n      filter: drop-shadow(0 0 10px rgba(0, 0, 0, 0.55));\n    }\n    .orb-icon svg { grid-area: 1 / 1; transition: opacity 380ms ease, rotate 640ms cubic-bezier(0.34, 1.42, 0.46, 1); }\n    .icon-moon { opacity: 0; rotate: -60deg; }\n    body.dark .icon-sun  { opacity: 0; rotate: 60deg; }\n    body.dark .icon-moon { opacity: 1; rotate: 0deg; }\n\n    @media (prefers-reduced-motion: reduce) {\n      body, .pill, .lab, .carrier, .orb-icon svg { transition-duration: 0.01s; }\n      .scene.is-moving .carrier { animation-duration: 0.01s; }\n    }\n  '
BODY = '  <button class="scene" id="toggle" role="switch" aria-checked="false" aria-label="テーマを切り替え（Light / Dark）">\n    <span class="pill">\n      <span class="lab lab-light">Light</span>\n      <span class="lab lab-dark">Dark</span>\n    </span>\n    <span class="carrier">\n      <span class="orb-slot">\n        <canvas id="orb" aria-label="Animated liquid glass orb"></canvas>\n      </span>\n      <span class="orb-icon" aria-hidden="true">\n        <svg class="icon-sun" width="60" height="60" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round">\n          <circle cx="12" cy="12" r="4.1" fill="currentColor" stroke="none"/>\n          <path d="M12 2.6v2.4M12 19v2.4M2.6 12h2.4M19 12h2.4M5.4 5.4l1.7 1.7M16.9 16.9l1.7 1.7M18.6 5.4l-1.7 1.7M7.1 16.9l-1.7 1.7"/>\n        </svg>\n        <svg class="icon-moon" width="54" height="54" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">\n          <path d="M20.5 14.5A8.5 8.5 0 0 1 9.5 3.5a8.5 8.5 0 1 0 11 11z" fill="currentColor" stroke="none"/>\n        </svg>\n      </span>\n    </span>\n  </button>\n'
SCRIPT = '  <script type="module">\n    // ── トグルの振る舞い。orb 本体の実行時JSは無改変 ──\n    // クリックで球が反対端へスライドし、テーマがクロスフェード。\n    // 移動中は流体を thinking に燃やし、着地後 idle に鎮める。\n    const scene = document.getElementById("toggle");\n    let settleTimer = 0;\n    scene.addEventListener("click", () => {\n      const dark = document.body.classList.toggle("dark");\n      scene.setAttribute("aria-checked", String(dark));\n      scene.classList.remove("is-moving");\n      void scene.offsetWidth;\n      scene.classList.add("is-moving");\n      // 球の色はテーマに追随: idle=ライトの白 / thinking=ダークのガラス。\n      // 内蔵の sRGB クロスフェード(0.65s)がスライドと同時に色を溶かす。\n      try { window.liquidOrb.setState(dark ? "thinking" : "idle"); } catch {}\n    });\n    scene.querySelector(".carrier").addEventListener("animationend", () => {\n      scene.classList.remove("is-moving");\n    });\n  </script>\n'
src = re.sub(r'<style>.*?</style>', lambda m: '<style>' + STYLE + '</style>', src, count=1, flags=re.S)
src = src.replace('  <canvas id="orb" aria-label="Animated liquid glass orb"></canvas>\n', BODY)
src = src.replace('</body>', SCRIPT + '</body>')
assert 'canvas id="orb"' in src and 'id="toggle"' in src
pathlib.Path('liquid-orb.html').write_text(src)
print('composed', len(src))
